import Domain
import Foundation

// MARK: - Transcription Plugins (Stubs)

public actor ParakeetPlugin: TranscriptionEngine {
    public init() {}
    public func loadModel(_: ModelID) async throws {}
    public func transcribe(samples: [Float], context _: TranscriptionContext) async throws -> TranscriptionSegment {
        return TranscriptionSegment(
            id: SegmentID(rawValue: UUID().uuidString),
            text: "[Parakeet Stub Output]",
            startTime: 0,
            endTime: Double(samples.count) / 16000.0,
            confidence: 1.0,
            isFinal: true,
            sequenceNumber: 0
        )
    }

    public func isReady() async -> Bool {
        return true
    }

    public func warmUp() async throws {}
}

public actor WhisperKitPlugin: TranscriptionEngine {
    public init() {}
    public func loadModel(_: ModelID) async throws {}
    public func transcribe(samples: [Float], context _: TranscriptionContext) async throws -> TranscriptionSegment {
        return TranscriptionSegment(
            id: SegmentID(rawValue: UUID().uuidString),
            text: "[Whisper Stub Output]",
            startTime: 0,
            endTime: Double(samples.count) / 16000.0,
            confidence: 1.0,
            isFinal: true,
            sequenceNumber: 0
        )
    }

    public func isReady() async -> Bool {
        return true
    }

    public func warmUp() async throws {}
}

// MARK: - Summarization Plugin (Stub)

public actor MLXSummarizationPlugin: SummarizationEngine {
    public init() {}
    public func loadModel(_: SummaryConfig) async throws {}
    public func summarize(transcript _: String, speakers _: [String], meetingType _: MeetingType) async throws -> MeetingSummary {
        return MeetingSummary(
            summary: "Stub Summary",
            decisions: [],
            actionItems: [],
            topics: [],
            openQuestions: [],
            generatedAt: Date(),
            modelId: ModelID(rawValue: "stub-model"),
            processingTime: 0.1
        )
    }

    public func isReady() async -> Bool {
        return true
    }

    public func generate(prompt: String) async throws -> String {
        return "Stub Generated Response"
    }

    /// Add getRawResponse since PipelineRunner might use it for debug dumps
    public func getRawResponse(transcript _: String, speakers _: [String]) async throws -> String {
        return "Stub Raw Response"
    }

    public func buildPrompt(transcript _: String, speakers _: [String], meetingType _: MeetingType) async -> String {
        return "Stub Prompt"
    }

    public func countTokens(_: String) async -> Int {
        return 0
    }
}

// MARK: - Diarization Plugin (Stub)

public actor FluidDiarizationPlugin: DiarizationEngine {
    public init() {}
    public func prepare() async throws {}
    public func diarize(samples: [Float], sampleRate: Int) async throws -> [SpeakerSegment] {
        return [
            SpeakerSegment(
                speakerId: SpeakerID(rawValue: "SPEAKER_00"),
                startTime: 0,
                endTime: Double(samples.count) / Double(sampleRate),
                confidence: 1.0
            ),
        ]
    }

    public func isReady() async -> Bool {
        return true
    }
}

// MARK: - Audio File Loader (Stub)

public struct AudioFileLoader: AudioSampleLoader {
